INSERT INTO email_templates("email_template_id", "name", "subject", "template") VALUES (1, 'ticketQrCodeEmailTemplate', 'Potwierdzenie opłacenia rezerwacji', '<!DOCTYPE html><html><head><meta name="viewport" content="width=device-width" /><meta http-equiv="Content-Type" content="text/html; charset=UTF-8" /><link rel="stylesheet" type="text/css" href="http://fonts.googleapis.com/css?family=Ubuntu:regular,bold&subset=Latin-ext"><title>Simple Transactional Email</title><style type="text/css">body {background-color: #f6f6f6;font-family: Ubuntu, arial;-webkit-font-smoothing: antialiased;font-size: 14px;line-height: 1.4;margin: 0;padding: 0;-ms-text-size-adjust: 100%;-webkit-text-size-adjust: 100%;}div{margin: 20px;}.footer {width: 100%;color: #999999;text-align: center;font-size: 12px;}</style></head><body><div id="text"><p>Witaj ${userName},</p><p>Poni&#380;ej znajdziesz zakupione bilety. Sprawd&#378;, czy Organizator nie doda&#322; informacji dodatkowych o Wydarzeniu - je&#347;li tak, to znajdziesz je w za&#322;&#261;czniku.</p></div><div id="tickets">${qrCodes}</div><div class="footer"><p class="apple-link">Hello Poland Sp. z o.o.</p><p class="powered-by">Powered by Fream S.A.</p></div></body></html>')
INSERT INTO email_templates("email_template_id", "name", "subject", "template") VALUES (2, 'ticketQrCodeTemplate', 'Zakupiony Bilet', '<!DOCTYPE html><html><head><meta name="viewport" content="width=device-width" /><meta http-equiv="Content-Type" content="text/html; charset=UTF-8" /><link rel="stylesheet" type="text/css" href="http://fonts.googleapis.com/css?family=Ubuntu:regular,bold&subset=Latin-ext"><style type="text/css">body {background-color: #f6f6f6;font-family: Ubuntu, arial;-webkit-font-smoothing: antialiased;font-size: 14px;line-height: 1.4;margin: 0;padding: 0;-ms-text-size-adjust: 100%;-webkit-text-size-adjust: 100%;}table {background-color: white;border-collapse: collapse;border-color: #ff0026;border-width: 3px;border-style: solid;text-align: center;table-layout: fixed;width: 680px;margin: 30px auto;}td {border-color: #ff0026;border-width: 1px;border-style: dotted;padding: 5px;}.text-red {color: #ff0026;}.text-left {text-align: left;}.word-break {word-wrap: break-word;}</style></head><body><table><colgroup><col width="18%"><col width="68%"></colgroup><tr class="text-left"><td class="text-red">Numer transakcji:</td><td colspan="2">${P24_transactionNumber}</td></tr><tr class="text-left"><td class="text-red">Wydarzenie:</td><td colspan="2">${sightEventName}</td></tr><tr class="text-left"><td class="text-red">Data/godzina:</td><td colspan="2">${sightEventDate}</td></tr><tr><td colspan="3">${qrCode}</td></tr><tr><td><span class="text-red">Bilet:</span><br>${ticketName}</td><td class="word-break"><span class="text-red">Numer Biletu:</span><br>${ticketNumber}</td><td><span class="text-red">Cena:</span><br>${ticketPrice}</td></tr><tr><td class="text-red" colspan="3">Sprawd&#378;, czy Organizator nie do&#322;&#261;czy&#322; do tego e-maila za&#322;&#261;cznika. Cz&#281;sto mo&#380;esz tam znale&#378;&#263; dodatkowe informacje o Wydarzeniu.</td></tr></table></body></html>')
